export const NAV_ICON_ACTIVE = "#333333";
export const NAV_ICON_INACTIVE = "#979797";

type NavIconProps = {
  color?: string;
  active?: boolean;
};

function resolveNavIconColor({ color, active }: NavIconProps) {
  return color ?? (active ? NAV_ICON_ACTIVE : NAV_ICON_INACTIVE);
}

